function y({registerIndicator:m,sourceValues:d,nulls:f}){m({id:"oa-epma",name:"Endpoint Moving Average (EPMA)",category:"Trends FIR",placement:"onchart",inputs:[{key:"period",type:"number",label:"Period",default:10,min:1,max:1e3,step:1},{key:"source",type:"source",label:"Source",default:"close"}],plots:[{key:"epma",type:"line",title:"EPMA",style:{color:"#ffeb3b",lineWidth:2}}],calc(l,r){const h=Math.max(1,Math.min(1e3,Math.floor(Number(r.period)||10))),o=d(l,r.source??"close"),c=l.length,n=new Array(c).fill(NaN);for(let e=0;e<c;e++){const i=Math.max(1,Math.min(e+1,h));if(i<=1){n[e]=Number.isFinite(o[e])?o[e]:NaN;continue}let p=0,a=0;for(let t=0;t<i;t++){const s=o[e-t];if(!Number.isFinite(s))continue;const u=i-t;p+=s*u,a+=u}n[e]=a>0?p/a:NaN}return{epma:f(n)}}})}export{y as default};
